import sys

with open(sys.argv[1], 'r') as f:
    lines = f.readlines()

def extract_function(target):
    in_func = False
    decorators = []
    start = None
    end = None
    for i, line in enumerate(lines):
        stripped = line.strip()
        if stripped.startswith('@'):
            if not in_func:
                decorators.append(line.rstrip())
        elif stripped.startswith(f'def {target}('):
            start = i - len(decorators)
            in_func = True
        if in_func:
            # find end of function (next line with same indentation as def)
            if start is not None and i > start:
                # naive: look for empty line after function? Use parsing but simple: continue until we reach a line with less indent than def line
                if i == start:
                    def_indent = len(line) - len(line.lstrip())
                else:
                    if stripped == '':
                        continue
                    current_indent = len(line) - len(line.lstrip())
                    if current_indent < def_indent:
                        # function ended at previous line
                        end = i
                        break
    if end is None:
        end = len(lines)
    # combine lines
    extracted = lines[start:end]
    return ''.join(extracted).rstrip()

targets = ['rms_norm_gated', '_layer_norm_fwd', '_layer_norm_fwd_1pass_kernel']
output = {}
for target in targets:
    output[target] = extract_function(target)

import json
print(json.dumps(output, indent=2))
